/**
 * Layout hint for skeleton sizing before data loads.
 */
export type DashboardWidgetMetaSize = typeof DashboardWidgetMetaSize[keyof typeof DashboardWidgetMetaSize];


export const DashboardWidgetMetaSize = {
  sm: 'sm',
  md: 'md',
  lg: 'lg',
} as const;

/**
 * Manifest metadata for a single dashboard widget. Contains key, title, and size only — never widget payload data (rows, values, etc.).
 */
export interface DashboardWidgetMeta {
  /** Stable identifier matching the WIDGET_CATALOG key. */
  key: string;
  /** Display label for the widget header. */
  title: string;
  /** Layout hint for skeleton sizing before data loads. */
  size: DashboardWidgetMetaSize;
}

/**
 * A single widget's position and size within the 12-column resizable dashboard grid. x/y are zero-indexed column/row coordinates; w/h are column-span and row-span respectively.
 */
export interface GridCellEntry {
  /** Widget key — matches WIDGET_CATALOG key. */
  key: string;
  /**
     * Column index (0–11).
     * @minimum 0
     * @maximum 11
     */
  x: number;
  /**
     * Row index (0-based). Upper bound prevents runaway stored values.
     * @minimum 0
     * @maximum 999
     */
  y: number;
  /**
     * Width in grid columns (1–12).
     * @minimum 1
     * @maximum 12
     */
  w: number;
  /**
     * Height in grid rows (1–20).
     * @minimum 1
     * @maximum 20
     */
  h: number;
}

export interface DashboardManifestEnvelope {
  /** Ordered list of widgets this user is permitted to see. */
  widgets: DashboardWidgetMeta[];
  /**
     * Stored per-user grid positions. Null when the user has never saved a custom layout; the frontend derives defaults from widget sizes.
     * @maxItems 50
     */
  gridLayout?: GridCellEntry[] | null;
}

/**
 * Layout hint for skeleton sizing.
 */
export type DashboardLayoutWidgetEntrySize = typeof DashboardLayoutWidgetEntrySize[keyof typeof DashboardLayoutWidgetEntrySize];


export const DashboardLayoutWidgetEntrySize = {
  sm: 'sm',
  md: 'md',
  lg: 'lg',
} as const;

/**
 * A widget entry with its current visibility state.
 */
export interface DashboardLayoutWidgetEntry {
  /** Stable identifier matching the WIDGET_CATALOG key. */
  key: string;
  /** Display label for the widget header. */
  title: string;
  /** Layout hint for skeleton sizing. */
  size: DashboardLayoutWidgetEntrySize;
  /** True if this widget is currently hidden by the user's stored layout. Granted widgets with hidden:true are excluded from the dashboard manifest but appear here so settings UIs can toggle them back on individually. */
  hidden: boolean;
}

/**
 * Full capability-resolved widget set with visibility state. Used by the settings UI; the dashboard grid should use GET /dashboard/manifest instead.
 */
export interface DashboardLayoutEnvelope {
  /** All granted widgets in display order (visible first per stored order, then hidden ones appended in catalog order). Each row includes a hidden flag indicating current visibility preference. */
  widgets: DashboardLayoutWidgetEntry[];
}

/**
 * User's widget layout preferences. All fields are optional — omitted fields are preserved from the existing stored layout. Hidden keys subtract from the capability-resolved set; order keys sort the result; gridLayout stores per-widget drag/resize positions. Unknown or uncapable keys are silently ignored at manifest resolution time.
 */
export interface DashboardLayoutInput {
  /**
     * Widget keys to hide from the dashboard.
     * @maxItems 50
     */
  hidden?: string[];
  /**
     * Desired display order of widget keys (front of list first).
     * @maxItems 50
     */
  order?: string[];
  /**
     * Per-widget grid positions. Pass null to clear saved positions and revert to catalog-size defaults.
     * @maxItems 50
     */
  gridLayout?: GridCellEntry[] | null;
}

